-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["5903870d961c9c4e"] = { "E il capo Var'gazul, al sicuro dietro le montagne di ⟦Zul'Gurub=Zul'gurub⟧, uscì nella giungla e la trovò spazzata via del suo popolo.\n\nE si disperò, perché i suoi sogni di conquista erano infranti.\n\nE Min'loth il Serpente non fu mai ritrovato.", "." },
  ["591fda09d240e042"] = { "Se avessi saputo cosa sarebbe successo, mi sarei tagliato la mano pur di non afferrare quel legno inciso di rune. Quanti rimpianti! Ho sempre pensato che fossero un privilegio dei vecchi. Ora so che non sono i vecchi, ma i disperati, a indossare il manto del rimpianto, incapaci e restii a scrollarselo dalle spalle curve per la miseria.\n\nMa basta divagare come un poeta impazzito per la pipa. Devo continuare la cronaca...", "." },
  ["5973cc032ec16bb4"] = { "Anche Ysera, la Sognatrice, pose un incantesimo sull'Albero del Mondo, legandolo al suo regno, la dimensione eterea nota come ⟦The Emerald Dream=Sogno di Smeraldo⟧. Il ⟦The Emerald Dream=Sogno di Smeraldo⟧, un vasto mondo spirituale in continuo mutamento, esisteva al di fuori dei confini del mondo fisico. Dal Sogno, Ysera regolava il flusso e riflusso della natura e il percorso evolutivo del mondo stesso.", "." },
  ["59c839c6b0612254"] = { "Tommy Joe,\n\nogni ora che passa il mio cuore appassisce per la tua assenza. Oh, se solo le nostre famiglie riuscissero a vedere oltre gli sciocchi torti che si sono fatte a vicenda, e capissero che l'unico vero crimine è l'odio. L'odio divora, e temo che in questi tempi sempre più bui l'odio si impadronirà di molto più che delle nostre famiglie.\n\nSe lo capissero, finalmente potremmo stare insieme. È per quel giorno che spero, ed è per quel giorno che vivo.\n\nLa tua amata,\nMaybell", "." },
  ["59ec1685e19c1299"] = { "E poi le acque si abbatterono sulla giungla, spazzando via tutto ciò che incontravano. Troll e bestie gridarono mentre le acque li travolgevano e li annegavano.\n\nMolti Gurubashi si chiesero perché l'oceano li inghiottisse, ma poi morirono e non seppero più nulla.\n\nE infine, quando le acque raggiunsero le montagne, si fermarono. Placate, si ritirarono oltre le rive, lasciando una scia di morte.\n\nSi ritirarono, ma restarono a circondare I'lalai, sommergendola per sempre.", "." },
})
